/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * Verify-After-Act Workflow (Method #15 variant for FM-3.3)
 *
 * Targets bob's FM-3.3 pattern: claiming deliverables are done without
 * running verification commands. Forces a mandatory verification pass
 * in a SEPARATE session after the work session completes.
 *
 * Unlike the generic two-phase workflow (analyze→act), this is act→verify:
 * - Phase 1: Do the actual work (write briefs, update configs, create docs)
 * - Phase 2: Verify every deliverable claimed in Phase 1 actually exists
 *   and contains expected content. Run `read()`, `ls`, `grep` to confirm.
 *
 * ## Task Format
 *
 * ```
 * agent: bob
 *
 * <work instructions — what to produce>
 *
 * ---
 *
 * VERIFICATION CHECKLIST (auto-generated from Phase 1 output):
 * For every file mentioned as written/modified in Phase 1:
 * 1. read() the file — confirm it exists
 * 2. Check it contains the expected content (not empty, not placeholder)
 * 3. If any file is missing or wrong, fix it now
 * Report: list each file with ✅ (verified) or ❌ (missing/wrong + fixed)
 * ```
 *
 * ## Evidence
 *
 * Bob FM-3.3: 6 occurrences (2026-03-17). Text coaching confirmed 0%
 * effective (exp-053: 0/5). Workflow enforcement ~92-97% effective across
 * 5 agents, 5 scenarios, 3 models. This variant specifically targets
 * the skip-verification pattern.
 */

export const name: string = "verify-after-act";

export const description: string =
  "Act-then-verify workflow: do work in Phase 1, then verify all deliverables " +
  "in a separate Phase 2 session. Targets FM-3.3 (verification failure) by " +
  "mechanically forcing a dedicated verification pass. " +
  "Task format: work instructions, then ---, then verification instructions. " +
  "If no Phase 2 provided, auto-generates a verification checklist. " +
  "Optional 'agent: <name>' header (default: bob).";

// ── Task Parser ────────────────────────────────────────────────────────

interface ParsedTask {
  agent: string;
  workPhase: string;
  verifyPhase: string | null; // null = auto-generate from Phase 1 output
}

const SEPARATOR = /\n---\n/;
const AGENT_LINE = /^agent:\s*(\S+)\s*$/im;

function parseTask(raw: string): ParsedTask {
  let agent = "bob";
  const agentMatch = raw.match(AGENT_LINE);
  if (agentMatch) {
    agent = agentMatch[1];
    raw = raw.replace(AGENT_LINE, "").trim();
  }

  const parts = raw.split(SEPARATOR);
  const workPhase = parts[0].trim();

  if (!workPhase) throw new Error("Work phase instructions are empty");

  // Phase 2 is optional — if not provided, auto-generate verification
  const verifyPhase = parts.length >= 2 ? parts.slice(1).join("\n---\n").trim() : null;

  return { agent, workPhase, verifyPhase };
}

// ── Deliverable Extraction ─────────────────────────────────────────────

/** Extract file paths mentioned in Phase 1 output for verification */
function extractDeliverables(phase1Output: string): string[] {
  const paths: string[] = [];
  // Match file paths in common patterns
  const patterns = [
    /(?:wrote|written|created|updated|modified|saved|generated)\s+(?:to\s+)?[`"']?([a-zA-Z0-9_./-]+\.\w+)[`"']?/gi,
    /(?:write|edit|create)\s+(?:to\s+)?[`"']?([a-zA-Z0-9_./-]+\.\w+)[`"']?/gi,
    /✅.*?[`"']([a-zA-Z0-9_./-]+\.\w+)[`"']/gi,
    /deliverable.*?[`"']([a-zA-Z0-9_./-]+\.\w+)[`"']/gi,
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(phase1Output)) !== null) {
      const path = match[1];
      if (!paths.includes(path) && !path.startsWith("http")) {
        paths.push(path);
      }
    }
  }

  return paths;
}

// ── Workflow Execute ───────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  let parsed: ParsedTask;
  try {
    parsed = parseTask(ctx.task);
  } catch (err) {
    return ctx.escalate(
      err instanceof Error ? err.message : "Failed to parse verify-after-act task",
      { rawTask: ctx.task.slice(0, 500) },
    );
  }

  const { agent, workPhase, verifyPhase } = parsed;

  // ── Phase 1: Work ────────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase1-work" });

  // Add verification awareness to Phase 1
  const phase1Task =
    workPhase +
    "\n\n" +
    "⚠️ IMPORTANT: After completing your work, list EVERY file you wrote or modified " +
    "with its full path. This list will be used for automated verification in the next phase.";

  const phase1Result = await ctx.runAgent(agent, phase1Task);

  if (phase1Result.status === "error") {
    return ctx.escalate("Phase 1 (work) failed", {
      agent,
      error: phase1Result.error,
      phase: 1,
    });
  }

  // ── Phase 2: Verify ─────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase2-verify" });

  let phase2Task: string;

  if (verifyPhase) {
    // Explicit verification instructions provided
    phase2Task = verifyPhase;
  } else {
    // Auto-generate verification checklist from Phase 1 output
    const deliverables = extractDeliverables(
      phase1Result.lastAssistantText ?? "",
    );

    if (deliverables.length > 0) {
      const fileList = deliverables.map((d) => `  - \`${d}\``).join("\n");
      phase2Task =
        `## Verification Pass (FM-3.3 Prevention)\n\n` +
        `Phase 1 claimed to produce these deliverables:\n${fileList}\n\n` +
        `For EACH file above:\n` +
        `1. \`read()\` the file — confirm it exists on disk\n` +
        `2. Check it contains substantive content (not empty, not placeholder)\n` +
        `3. If the file is MISSING or EMPTY, recreate it now\n\n` +
        `Also check: were any other files mentioned as modified in Phase 1? ` +
        `Read back those too.\n\n` +
        `Report format:\n` +
        `- \`path/to/file.md\` — ✅ exists, N lines, contains [summary]\n` +
        `- \`path/to/other.md\` — ❌ MISSING → recreated\n\n` +
        `Do NOT mark anything verified without actually reading it.`;
    } else {
      phase2Task =
        `## Verification Pass (FM-3.3 Prevention)\n\n` +
        `Phase 1 completed but no specific deliverables were extracted from its output.\n\n` +
        `Review what Phase 1 was supposed to produce (original task: "${workPhase.slice(0, 200)}...").\n\n` +
        `1. Identify what files SHOULD have been written/modified\n` +
        `2. \`read()\` each one to confirm it exists and has correct content\n` +
        `3. If anything is missing, create it now\n\n` +
        `Report each file with ✅ verified or ❌ missing/fixed.`;
    }
  }

  const phase2Result = await ctx.runAgent(agent, phase2Task);

  if (phase2Result.status === "error") {
    return ctx.escalate("Phase 2 (verification) failed", {
      agent,
      error: phase2Result.error,
      phase: 2,
      phase1Summary: phase1Result.lastAssistantText?.slice(0, 1000),
    });
  }

  // ── Result ─────────────────────────────────────────────────────────

  return ctx.done(
    `## Verify-After-Act Workflow Complete\n\n` +
      `**Agent**: ${agent}\n\n` +
      `### Phase 1: Work\n` +
      `${phase1Result.lastAssistantText ?? "(no output)"}\n\n` +
      `### Phase 2: Verification\n` +
      `${phase2Result.lastAssistantText ?? "(no output)"}`,
  );
}

